<?php
namespace App\Http\Requests;use App\Services\Team\TeamAuthorization;use App\Support\WatermarkPosition;use Illuminate\Foundation\Http\FormRequest;use Illuminate\Validation\Rule;
class UpdateWatermarkSettingsRequest extends FormRequest{public function authorize():bool{$o=app(TeamAuthorization::class)->ownerFor($this->user());return$o&&app(TeamAuthorization::class)->allows($this->user(),$o,'manage_watermark');}public function rules():array{return['size_percentage'=>['required','integer','between:1,99'],'position'=>['required',Rule::in(WatermarkPosition::VALUES)],'logo'=>['nullable','file','mimes:png,jpg,jpeg,webp','mimetypes:image/png,image/jpeg,image/webp','max:2048'],'remove_logo'=>['sometimes','boolean']];}public function messages():array{return['size_percentage.between'=>'Watermark size must be between 1 and 99.','position.in'=>'Please select a valid watermark position.','logo.max'=>'Please select an image smaller than 2 MB.'];}}
